@dataclasses.dataclass(frozen=True)
class SfPart:
    part_id: int
    month: str
    block: str
    path: Path
    rows: int
    size_bytes: int
    schema_signature: tuple[tuple[str, str, bool], ...]


def utc_now() -> str:
    return dt.datetime.now(dt.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def run_id() -> str:
    return dt.datetime.now(dt.timezone.utc).strftime("%Y%m%dT%H%M%SZ") + f"_{os.getpid()}"


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(4 * 1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def jsonable(value: Any) -> Any:
    if dataclasses.is_dataclass(value):
        return jsonable(dataclasses.asdict(value))
    if isinstance(value, Path):
        return str(value)
    if isinstance(value, Decimal):
        return float(value)
    if isinstance(value, dict):
        return {str(key): jsonable(child) for key, child in value.items()}
    if isinstance(value, (list, tuple, set)):
        return [jsonable(child) for child in value]
    if hasattr(value, "item"):
        return value.item()
    if isinstance(value, float) and not math.isfinite(value):
        return None
    return value


def atomic_write_json(path: Path, payload: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temp = path.with_name(path.name + f".tmp.{uuid.uuid4().hex}")
    temp.write_text(
        json.dumps(jsonable(payload), indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    os.replace(temp, path)


def atomic_write_text(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temp = path.with_name(path.name + f".tmp.{uuid.uuid4().hex}")
    temp.write_text(text, encoding="utf-8")
    os.replace(temp, path)


def sql_literal(value: str | Path) -> str:
    return "'" + str(value).replace("'", "''") + "'"


def quote_identifier(value: str) -> str:
    return '"' + value.replace('"', '""') + '"'


def schema_signature(schema: pa.Schema) -> tuple[tuple[str, str, bool], ...]:
    return tuple((field.name, str(field.type), bool(field.nullable)) for field in schema)


def month_from_path(path: Path) -> str:
    match = re.search(r"month=([0-9]{4}-[0-9]{2})", str(path))
    if match is None:
        raise RuntimeError(f"No month=YYYY-MM partition in path: {path}")
    return match.group(1)


def sf_block(path: Path) -> str:
    text = str(path)
    if "STOCKFISH100K_EXISTING_11M_2023-11_TO_2024-09" in text:
        return "early"
    if "STOCKFISH100K_BRIDGE_2024-10_TO_2025-07" in text:
        return "bridge"
    if "STOCKFISH100K_AUG_TO_OCT_2025" in text:
        return "late"
    raise RuntimeError(f"Unrecognized certified Stockfish source block: {path}")


def parse_months(raw: str) -> tuple[str, ...]:
    if raw.strip().lower() in {"all", "*"}:
        return MONTHS
    requested = tuple(item.strip() for item in raw.split(",") if item.strip())
    if not requested:
        raise SystemExit("--months resolved to an empty month list")
    unknown = [month for month in requested if month not in MONTH_ROWS]
    if unknown:
        raise SystemExit(f"Unknown/out-of-sample months: {unknown}")
    if len(set(requested)) != len(requested):
        raise SystemExit("--months contains duplicates")
    return tuple(month for month in MONTHS if month in set(requested))


def git_output(*args: str, check: bool = True) -> str:
    result = subprocess.run(
        ["git", *args],
        cwd=REPO,
        check=check,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.STDOUT,
    )
    return result.stdout.strip()


def verify_git_state(script_path: Path) -> dict[str, Any]:
    if not (REPO / ".git").is_dir():
        raise RuntimeError(f"Canonical Git repository missing: {REPO}")
    head = git_output("rev-parse", "HEAD")
    ancestor = subprocess.run(
        ["git", "merge-base", "--is-ancestor", EXPECTED_BASE_COMMIT, head],
        cwd=REPO,
        check=False,
    ).returncode == 0
    if not ancestor:
        raise RuntimeError(
            f"Current HEAD {head} does not descend from authenticated base {EXPECTED_BASE_COMMIT}"
        )
    status_lines = [line for line in git_output("status", "--porcelain=v1").splitlines() if line]
    try:
        relative_script = str(script_path.resolve().relative_to(REPO.resolve()))
    except ValueError:
        relative_script = None
    unrelated = []
    for line in status_lines:
        path_text = line[3:] if len(line) >= 4 else line
        if relative_script is None or path_text != relative_script:
            unrelated.append(line)
    if unrelated:
        raise RuntimeError(
            "Unrelated Git worktree changes are present; fail closed:\n" + "\n".join(unrelated)
        )
    return {
        "head": head,
        "branch": git_output("branch", "--show-current"),
        "origin": git_output("remote", "get-url", "origin"),
        "status_lines": status_lines,
        "expected_base_is_ancestor": ancestor,
    }


def verify_small_authorities() -> dict[str, str]:
    observed: dict[str, str] = {}
    for path, expected in EXPECTED_SMALL_SHA256.items():
        if not path.is_file():
            raise RuntimeError(f"Required frozen authority missing: {path}")
        actual = sha256_file(path)
        observed[str(path)] = actual
        if actual != expected:
            raise RuntimeError(
                f"Frozen authority hash changed: {path}\nexpected={expected}\nactual={actual}"
            )
    return observed


def verify_summary_contracts() -> dict[str, Any]:
    stage05 = json.loads(STAGE05_SUMMARY.read_text(encoding="utf-8"))
    stage06 = json.loads(STAGE06_SUMMARY.read_text(encoding="utf-8"))
    sf_cert = json.loads(SF_CERT.read_text(encoding="utf-8"))

    required = [
        (stage05.get("final_ok") is True, "Stage 05 final_ok is not true"),
        (
            stage05.get("total_timeout_opportunities") == EXPECTED_ROWS,
            "Stage 05 total_timeout_opportunities changed",
        ),
        (
            stage05.get("outcome_kind_draws") == EXPECTED_KIND_DRAWS,
            "Stage 05 outcome_kind_draws changed",
        ),
        (
            stage05.get("timeout_chooser_losses") == EXPECTED_CHOOSER_LOSSES,
            "Stage 05 timeout_chooser_losses changed",
        ),
        (stage06.get("final_ok") is True, "Stage 06 final_ok is not true"),
        (stage06.get("total_rows") == EXPECTED_ROWS, "Stage 06 total_rows changed"),
        (
            stage06.get("both_ratingdiff_null_rows") == EXPECTED_BOTH_RATINGDIFF_NULL,
            "Stage 06 both-ratingDiff-null count changed",
        ),
        (sf_cert.get("status") == "certified_ok", "Stockfish certification is not certified_ok"),
        (sf_cert.get("total_rows") == EXPECTED_ROWS, "Stockfish certified total_rows changed"),
        (sf_cert.get("n_parquet_files") == EXPECTED_SF_PARTS, "Stockfish part count changed"),
        (sf_cert.get("total_error_rows") == 0, "Stockfish certification has error rows"),
    ]
    failures = [message for condition, message in required if not condition]
    if failures:
        raise RuntimeError("Frozen summary contract failure:\n" + "\n".join(failures))
    return {"stage05": stage05, "stage06": stage06, "stockfish": sf_cert}


def discover_sf_parts() -> list[SfPart]:
    raw_paths = [
        Path(line.strip())
        for line in SF_PATH_LIST.read_text(encoding="utf-8").splitlines()
        if line.strip()
    ]
    if len(raw_paths) != EXPECTED_SF_PARTS:
        raise RuntimeError(f"Expected {EXPECTED_SF_PARTS} Stockfish paths; found {len(raw_paths)}")
    if len(set(raw_paths)) != len(raw_paths):
        raise RuntimeError("Certified Stockfish path list contains duplicate paths")

    parts: list[SfPart] = []
    for part_id, path in enumerate(raw_paths):
        if not path.is_file():
            raise RuntimeError(f"Certified Stockfish path is missing: {path}")
        parquet = pq.ParquetFile(path)
        schema = parquet.schema_arrow
        missing = [name for name in SF_REQUIRED_COLUMNS if name not in schema.names]
        if missing:
            raise RuntimeError(f"Stockfish file lacks required fields {missing}: {path}")
        parts.append(
            SfPart(
                part_id=part_id,
                month=month_from_path(path),
                block=sf_block(path),
                path=path,
                rows=parquet.metadata.num_rows,
                size_bytes=path.stat().st_size,
                schema_signature=schema_signature(schema),
            )
        )
    if sum(part.rows for part in parts) != EXPECTED_ROWS:
        raise RuntimeError("Stockfish footer rows no longer equal the certified total")
    return parts


def monthly_input_path(root: Path, month: str, filename: str) -> Path:
    return root / f"month={month}" / filename


def verify_monthly_inputs(parts: Sequence[SfPart]) -> dict[str, dict[str, Any]]:
    sf_by_month: dict[str, list[SfPart]] = collections.defaultdict(list)
    for part in parts:
        sf_by_month[part.month].append(part)

    inventory: dict[str, dict[str, Any]] = {}
    for month, expected_rows in MONTH_ROWS.items():
        s05 = monthly_input_path(STAGE05_ROOT, month, "timeout_opportunities.parquet")
        s06 = monthly_input_path(STAGE06_ROOT, month, "chooser_glicko2_costs.parquet")
        for label, path in (("Stage 05", s05), ("Stage 06", s06)):
            if not path.is_file():
                raise RuntimeError(f"{label} monthly input missing: {path}")
        s05_pf = pq.ParquetFile(s05)
        s06_pf = pq.ParquetFile(s06)
        missing05 = [source for source, _ in STAGE05_COLUMNS if source not in s05_pf.schema_arrow.names]
        missing06 = [name for name in STAGE06_COLUMNS if name not in s06_pf.schema_arrow.names]
        if missing05:
            raise RuntimeError(f"Stage 05 fields missing for {month}: {missing05}")
        if missing06:
            raise RuntimeError(f"Stage 06 fields missing for {month}: {missing06}")
        sf_rows = sum(part.rows for part in sf_by_month.get(month, []))
        counts = (s05_pf.metadata.num_rows, s06_pf.metadata.num_rows, sf_rows)
        if counts != (expected_rows, expected_rows, expected_rows):
            raise RuntimeError(
                f"Monthly footer mismatch for {month}: Stage05/Stage06/SF={counts}; "
                f"expected {expected_rows}"
            )
        inventory[month] = {
            "expected_rows": expected_rows,
            "stage05_path": str(s05),
            "stage05_rows": counts[0],
            "stage05_size_bytes": s05.stat().st_size,
            "stage06_path": str(s06),
            "stage06_rows": counts[1],
            "stage06_size_bytes": s06.stat().st_size,
            "sf100k_rows": counts[2],
            "sf100k_parts": len(sf_by_month[month]),
            "sf100k_size_bytes": sum(part.size_bytes for part in sf_by_month[month]),
            "sf100k_blocks": sorted({part.block for part in sf_by_month[month]}),
        }
    return inventory


