def print_plan(
    *,
    months: Sequence[str],
    output_root: Path,
    parts: Sequence[SfPart],
    inventory: dict[str, dict[str, Any]],
    contract: dict[str, Any],
    git_state: dict[str, Any],
) -> None:
    variants: dict[tuple[tuple[str, str, bool], ...], list[SfPart]] = collections.defaultdict(list)
    for part in parts:
        variants[part.schema_signature].append(part)
    selected_rows = sum(MONTH_ROWS[month] for month in months)
    selected_bytes = sum(
        inventory[month]["stage05_size_bytes"]
        + inventory[month]["stage06_size_bytes"]
        + inventory[month]["sf100k_size_bytes"]
        for month in months
    )
    free_bytes = shutil.disk_usage(output_root.parent if output_root.parent.exists() else PROJECT).free

    print("STAGE07_PLAN_OK")
    print(f"script_version: {SCRIPT_VERSION}")
    print(f"script_sha256: {contract['script_sha256']}")
    print(f"git_head: {git_state['head']}")
    print(f"months: {','.join(months)}")
    print(f"selected_rows: {selected_rows:,}")
    print(f"output_root: {output_root}")
    print(f"planned_output_columns: {contract['output_column_count']}")
    print(f"certified_sf_parts_all_months: {len(parts)}")
    print(f"stockfish_exact_schema_variants: {len(variants)}")
    print(f"selected_input_bytes: {selected_bytes:,}")
    print(f"free_bytes_on_output_volume: {free_bytes:,}")
    print("\nMONTH INPUTS")
    for month in months:
        row = inventory[month]
        print(
            f"{month}: rows={row['expected_rows']:,} sf_parts={row['sf100k_parts']} "
            f"sf_blocks={','.join(row['sf100k_blocks'])}"
        )
    print("\nSOURCE AUTHORITY")
    for key, value in contract["source_authorities"].items():
        print(f"{key}: {value}")
    print("\nENGINE CONTRACT")
    print("source field: sf100k_eval_cp_disconnected")
    print("perspective: disconnected player")
    print("mate sentinel: +/-10000")
    print("terminal Mate(0): -10000, permitted only when FEN independently validates checkmate")
    print("nodes/depth telemetry exceptions: permitted only for validated terminal Mate(0)")
    print("optional Stockfish duplicate fields: diagnostic only; Stage 05 remains authority")
    print("fair: eval >= -100; clearly worse: eval <= -300")
    print("paper favorable/non-loss: chooser_draw_payoff_v2 >= 0")
    print("chooser cluster field: chooser_username_norm")
    print("sample-specific bins/z-scores: derive downstream, not in Stage 07")
    print("\nNo files were written. Re-run with --execute to build selected months.")


class RunLogger:
    def __init__(self, path: Path):
        self.path = path
        path.parent.mkdir(parents=True, exist_ok=True)

    def __call__(self, message: str) -> None:
        line = f"[{utc_now()}] {message}"
        print(line, flush=True)
        with self.path.open("a", encoding="utf-8") as stream:
            stream.write(line + "\n")


def one_row_dict(connection: duckdb.DuckDBPyConnection, sql: str) -> dict[str, Any]:
    cursor = connection.execute(sql)
    row = cursor.fetchone()
    if row is None:
        raise RuntimeError("Expected a one-row query result")
    names = [description[0] for description in cursor.description]
    return {name: jsonable(value) for name, value in zip(names, row)}


def scalar(connection: duckdb.DuckDBPyConnection, sql: str) -> Any:
    row = connection.execute(sql).fetchone()
    if row is None:
        raise RuntimeError("Expected a scalar query result")
    return row[0]


def assert_zero_fields(label: str, values: dict[str, Any], fields: Iterable[str]) -> None:
    failures = []
    for field in fields:
        value = values.get(field)
        if value != 0:
            failures.append(f"{field}={value}")
    if failures:
        raise RuntimeError(f"{label} fail-closed QA failed: " + ", ".join(failures))


def validate_terminal_mate_zero_rows(
    connection: duckdb.DuckDBPyConnection,
    *,
    month: str,
) -> dict[str, Any]:
    """Validate the narrow Stockfish terminal-position telemetry exception.

    python-chess represents a position in which the side to move has already
    been checkmated as Mate(0).  Its ``mate()`` accessor therefore returns 0,
    while ``score(mate_score=10000)`` is -10000.  Stockfish can return no
    searched-node/depth telemetry for such a terminal FEN because there is no
    search tree to explore.  We permit that telemetry shape only after parsing
    the stored FEN and independently proving that it is checkmate.
    """
    cursor = connection.execute(
        """
        SELECT
          game_id,
          fen_after_last_move,
          side_to_move_after_last,
          sf100k_fen_turn_color,
          sf100k_disconnected_color_for_perspective,
          sf100k_nodes_requested,
          sf100k_nodes_searched,
          sf100k_depth,
          sf100k_seldepth,
          sf100k_score_cp_side_to_move,
          sf100k_score_value_side_to_move,
          sf100k_mate_ply_side_to_move,
          sf100k_eval_cp_disconnected_raw,
          sf100k_eval_cp_disconnected,
          sf100k_eval_cp_disconnected_capped600,
          sf100k_eval_is_mate,
          sf100k_eval_mate_ply_disconnected
        FROM sf
        WHERE sf100k_score_type_side_to_move = 'mate'
          AND sf100k_score_value_side_to_move = 0
        ORDER BY game_id
        """
    )
    names = [description[0] for description in cursor.description]
    rows = [dict(zip(names, row)) for row in cursor.fetchall()]
    failures: list[str] = []
    telemetry_exception_rows = 0

    for row in rows:
        game_id = str(row["game_id"])
        try:
            board = chess.Board(str(row["fen_after_last_move"]))
        except ValueError as exc:  # pragma: no cover - production-data guard
            failures.append(f"{game_id}: invalid FEN ({type(exc).__name__}: {exc})")
            continue

        board_turn = "white" if board.turn == chess.WHITE else "black"
        row_failures: list[str] = []
        if not board.is_valid():
            row_failures.append(f"board_status={board.status()}")
        if not board.is_checkmate():
            row_failures.append("FEN is not checkmate")
        if board_turn != str(row["sf100k_fen_turn_color"]).lower():
            row_failures.append(
                f"FEN turn={board_turn} but stored turn={row['sf100k_fen_turn_color']}"
            )
        if board_turn != str(row["side_to_move_after_last"]).lower():
            row_failures.append(
                "FEN turn differs from side_to_move_after_last="
                f"{row['side_to_move_after_last']}"
            )
        if board_turn != str(row["sf100k_disconnected_color_for_perspective"]).lower():
            row_failures.append(
                "FEN turn differs from disconnected perspective="
                f"{row['sf100k_disconnected_color_for_perspective']}"
            )
        if row["sf100k_nodes_requested"] != 100000:
            row_failures.append(
                f"nodes_requested={row['sf100k_nodes_requested']} instead of 100000"
            )
        if row["sf100k_score_cp_side_to_move"] is not None:
            row_failures.append(
                f"score_cp_side_to_move={row['sf100k_score_cp_side_to_move']}"
            )
        if row["sf100k_mate_ply_side_to_move"] != 0:
            row_failures.append(
                f"mate_ply_side_to_move={row['sf100k_mate_ply_side_to_move']}"
            )
        if row["sf100k_eval_mate_ply_disconnected"] != 0:
            row_failures.append(
                "eval_mate_ply_disconnected="
                f"{row['sf100k_eval_mate_ply_disconnected']}"
            )
        if row["sf100k_eval_cp_disconnected_raw"] != -10000:
            row_failures.append(
                f"raw disconnected eval={row['sf100k_eval_cp_disconnected_raw']}"
            )
        if row["sf100k_eval_cp_disconnected"] != -10000:
            row_failures.append(
                f"disconnected eval={row['sf100k_eval_cp_disconnected']}"
            )
        if row["sf100k_eval_cp_disconnected_capped600"] != -600:
            row_failures.append(
                "capped disconnected eval="
                f"{row['sf100k_eval_cp_disconnected_capped600']}"
            )
        if row["sf100k_eval_is_mate"] is not True:
            row_failures.append(f"eval_is_mate={row['sf100k_eval_is_mate']}")

        if (
            row["sf100k_nodes_searched"] is None
            or row["sf100k_nodes_searched"] <= 0
            or row["sf100k_depth"] is None
            or row["sf100k_seldepth"] is None
        ):
            telemetry_exception_rows += 1

        if row_failures:
            failures.append(f"{game_id}: " + "; ".join(row_failures))

    if failures:
        raise RuntimeError(
            f"{month}: terminal Mate(0) semantic validation failed:\n"
            + "\n".join(failures)
        )

    game_ids = [str(row["game_id"]) for row in rows]
    game_id_bytes = "".join(f"{game_id}\n" for game_id in game_ids).encode("utf-8")
    return {
        "validated_rows": len(rows),
        "telemetry_exception_rows": telemetry_exception_rows,
        "game_ids": game_ids,
        "game_ids_sha256": hashlib.sha256(game_id_bytes).hexdigest(),
        "validation_rule": (
            "Mate(0), eval=-10000, mate ply=0, and chess.Board(FEN).is_checkmate()"
        ),
    }


def collect_optional_sf_duplicate_details(
    connection: duckdb.DuckDBPyConnection,
    *,
    mismatch_counts: dict[str, Any],
) -> dict[str, Any]:
    """Audit non-authoritative fields duplicated in the Stockfish layer.

    The engine layer was built from earlier analysis inputs and carries several
    convenience duplicates that Stockfish did not use. Stage 05 is the frozen
    authority for these fields. Mismatches are retained as provenance
    diagnostics, while the game/FEN/perspective/evaluation checks remain fatal.
    """
    specifications = (
        (
            "api_status",
            "s05.api_status",
            "sf.sf_api_status",
            "sf_optional_api_status_mismatch_rows",
        ),
        (
            "api_speed",
            "s05.api_speed",
            "sf.sf_api_speed",
            "sf_optional_speed_mismatch_rows",
        ),
        (
            "outcome_kind_draw",
            "s05.outcome_kind_draw",
            "sf.sf_outcome_kind_draw",
            "sf_duplicate_kind_diagnostic_mismatch_rows",
        ),
        (
            "timeout_draw",
            "s05.timeout_draw",
            "sf.sf_timeout_draw",
            "sf_duplicate_timeout_draw_diagnostic_mismatch_rows",
        ),
        (
            "chooser_has_mating_material",
            "s05.chooser_has_mating_material",
            "sf.sf_chooser_has_mating_material",
            "sf_duplicate_mating_diagnostic_mismatch_rows",
        ),
    )
    fields: dict[str, Any] = {}
    mismatch_field_rows = 0

    for label, authority_expression, duplicate_expression, count_field in specifications:
        expected_count = int(mismatch_counts[count_field])
        mismatch_field_rows += expected_count
        details: dict[str, Any] = {
            "mismatch_rows": expected_count,
            "value_pairs": [],
            "source_parts": [],
            "sample_rows": [],
            "all_game_ids_sha256": hashlib.sha256(b"").hexdigest(),
            "all_game_ids_hashed": True,
        }
        if expected_count == 0:
            fields[label] = details
            continue

        predicate = (
            f"{duplicate_expression} IS NOT NULL AND "
            f"{authority_expression} IS DISTINCT FROM {duplicate_expression}"
        )
        pair_cursor = connection.execute(
            f"""
            SELECT
              CAST({authority_expression} AS VARCHAR) AS stage05_value,
              CAST({duplicate_expression} AS VARCHAR) AS stockfish_duplicate_value,
              COUNT(*)::BIGINT AS rows
            FROM s05
            INNER JOIN sf ON s05.game_id = sf.game_id
            WHERE {predicate}
            GROUP BY 1, 2
            ORDER BY rows DESC, stage05_value, stockfish_duplicate_value
            """
        )
        pair_names = [description[0] for description in pair_cursor.description]
        details["value_pairs"] = [
            {name: jsonable(value) for name, value in zip(pair_names, row)}
            for row in pair_cursor.fetchall()
        ]

        part_cursor = connection.execute(
            f"""
            SELECT
              sf.sf100k_source_block,
              sf.sf100k_source_part_id,
              COUNT(*)::BIGINT AS rows
            FROM s05
            INNER JOIN sf ON s05.game_id = sf.game_id
            WHERE {predicate}
            GROUP BY 1, 2
            ORDER BY sf.sf100k_source_block, sf.sf100k_source_part_id
            """
        )
        part_names = [description[0] for description in part_cursor.description]
        details["source_parts"] = [
            {name: jsonable(value) for name, value in zip(part_names, row)}
            for row in part_cursor.fetchall()
        ]

        sample_cursor = connection.execute(
            f"""
            SELECT
              s05.game_id,
              CAST({authority_expression} AS VARCHAR) AS stage05_value,
              CAST({duplicate_expression} AS VARCHAR) AS stockfish_duplicate_value,
              sf.sf100k_source_block,
              sf.sf100k_source_part_id,
              sf.sf100k_source_path
            FROM s05
            INNER JOIN sf ON s05.game_id = sf.game_id
            WHERE {predicate}
            ORDER BY s05.game_id
            LIMIT 100
            """
        )
        sample_names = [description[0] for description in sample_cursor.description]
        details["sample_rows"] = [
            {name: jsonable(value) for name, value in zip(sample_names, row)}
            for row in sample_cursor.fetchall()
        ]

        if expected_count <= 100_000:
            id_rows = connection.execute(
                f"""
                SELECT s05.game_id
                FROM s05
                INNER JOIN sf ON s05.game_id = sf.game_id
                WHERE {predicate}
                ORDER BY s05.game_id
                """
            ).fetchall()
            if len(id_rows) != expected_count:
                raise RuntimeError(
                    f"Optional Stockfish duplicate detail count changed for {label}: "
                    f"expected={expected_count}, observed={len(id_rows)}"
                )
            id_bytes = "".join(f"{row[0]}\n" for row in id_rows).encode("utf-8")
            details["all_game_ids_sha256"] = hashlib.sha256(id_bytes).hexdigest()
        else:
            details["all_game_ids_sha256"] = None
            details["all_game_ids_hashed"] = False

        fields[label] = details

    return {
        "authority": "Stage 05",
        "stockfish_fields_are": "non-authoritative diagnostic duplicates",
        "mismatch_field_rows": mismatch_field_rows,
        "fields": fields,
    }


def configure_duckdb(
    connection: duckdb.DuckDBPyConnection,
    *,
    threads: int,
    memory_limit: str,
    temp_directory: Path,
) -> None:
    temp_directory.mkdir(parents=True, exist_ok=True)
    connection.execute(f"PRAGMA threads={int(threads)}")
    connection.execute(f"SET memory_limit={sql_literal(memory_limit)}")
    connection.execute(f"SET temp_directory={sql_literal(temp_directory)}")
    connection.execute("SET preserve_insertion_order=false")


def sf_manifest_table(parts: Sequence[SfPart]) -> pa.Table:
    return pa.table(
        {
            "sf100k_source_path": pa.array([str(part.path) for part in parts], type=pa.string()),
            "sf100k_source_part_id": pa.array([part.part_id for part in parts], type=pa.int16()),
            "sf100k_source_month": pa.array([part.month for part in parts], type=pa.string()),
            "sf100k_source_block": pa.array([part.block for part in parts], type=pa.string()),
        }
    )


def optional_sf_expression(union_names: set[str], name: str, sql_type: str, alias: str) -> str:
    if name in union_names:
        return f"TRY_CAST(r.{quote_identifier(name)} AS {sql_type}) AS {quote_identifier(alias)}"
    return f"CAST(NULL AS {sql_type}) AS {quote_identifier(alias)}"


def create_month_views(
    connection: duckdb.DuckDBPyConnection,
    *,
    month: str,
    parts: Sequence[SfPart],
) -> tuple[Path, Path]:
    stage05_path = monthly_input_path(STAGE05_ROOT, month, "timeout_opportunities.parquet")
    stage06_path = monthly_input_path(STAGE06_ROOT, month, "chooser_glicko2_costs.parquet")
    sf_paths_sql = ", ".join(sql_literal(part.path) for part in parts)
    union_names = {name for part in parts for name, _, _ in part.schema_signature}

    connection.register("sf_part_manifest_arrow", sf_manifest_table(parts))
    connection.execute("CREATE TEMP VIEW sf_part_manifest AS SELECT * FROM sf_part_manifest_arrow")
    connection.execute(
        f"CREATE TEMP VIEW s05 AS SELECT * FROM read_parquet({sql_literal(stage05_path)})"
    )
    connection.execute(
        f"CREATE TEMP VIEW s06 AS SELECT * FROM read_parquet({sql_literal(stage06_path)})"
    )
    connection.execute(
        "CREATE TEMP VIEW sf_raw AS "
        f"SELECT * FROM read_parquet([{sf_paths_sql}], union_by_name=true, filename=true)"
    )

    optional = [
        optional_sf_expression(union_names, "api_status", "VARCHAR", "sf_api_status"),
        optional_sf_expression(union_names, "api_speed", "VARCHAR", "sf_api_speed"),
        optional_sf_expression(
            union_names, "outcome_kind_draw", "BOOLEAN", "sf_outcome_kind_draw"
        ),
        optional_sf_expression(
            union_names,
            "chooser_has_mating_material",
            "BOOLEAN",
            "sf_chooser_has_mating_material",
        ),
        optional_sf_expression(union_names, "timeout_draw", "BOOLEAN", "sf_timeout_draw"),
    ]

    connection.execute(
        f"""
        CREATE TEMP VIEW sf AS
        SELECT
          CAST(r.game_id AS VARCHAR) AS game_id,
          CAST(r.month AS VARCHAR) AS month,
          CAST(r.side_to_move_after_last AS VARCHAR) AS side_to_move_after_last,
          CAST(r.fen_after_last_move AS VARCHAR) AS fen_after_last_move,
          TRY_CAST(r.sf100k_ok AS BOOLEAN) AS sf100k_ok,
          CAST(r.sf100k_stockfish_name AS VARCHAR) AS sf100k_stockfish_name,
          CAST(r.sf100k_stockfish_sha256 AS VARCHAR) AS sf100k_stockfish_sha256,
          TRY_CAST(r.sf100k_nodes_requested AS BIGINT) AS sf100k_nodes_requested,
          TRY_CAST(r.sf100k_nodes_searched AS BIGINT) AS sf100k_nodes_searched,
          TRY_CAST(r.sf100k_threads AS BIGINT) AS sf100k_threads,
          TRY_CAST(r.sf100k_hash_mb AS BIGINT) AS sf100k_hash_mb,
          TRY_CAST(r.sf100k_depth AS BIGINT) AS sf100k_depth,
          TRY_CAST(r.sf100k_seldepth AS BIGINT) AS sf100k_seldepth,
          CAST(r.sf100k_eval_method AS VARCHAR) AS sf100k_eval_method,
          CAST(r.sf100k_fen_turn_color AS VARCHAR) AS sf100k_fen_turn_color,
          CAST(r.sf100k_disconnected_color_for_perspective AS VARCHAR)
            AS sf100k_disconnected_color_for_perspective,
          CAST(r.sf100k_perspective_assumption AS VARCHAR) AS sf100k_perspective_assumption,
          TRY_CAST(r.sf100k_fen_turn_matches_disconnected_color AS BOOLEAN)
            AS sf100k_fen_turn_matches_disconnected_color,
          CAST(r.sf100k_score_type_side_to_move AS VARCHAR) AS sf100k_score_type_side_to_move,
          TRY_CAST(r.sf100k_score_value_side_to_move AS BIGINT)
            AS sf100k_score_value_side_to_move,
          TRY_CAST(r.sf100k_score_cp_side_to_move AS DOUBLE) AS sf100k_score_cp_side_to_move,
          TRY_CAST(r.sf100k_mate_ply_side_to_move AS DOUBLE) AS sf100k_mate_ply_side_to_move,
          TRY_CAST(r.sf100k_eval_cp_disconnected_raw AS BIGINT)
            AS sf100k_eval_cp_disconnected_raw,
          TRY_CAST(r.sf100k_eval_cp_disconnected AS BIGINT) AS sf100k_eval_cp_disconnected,
          TRY_CAST(r.sf100k_eval_cp_disconnected_capped600 AS BIGINT)
            AS sf100k_eval_cp_disconnected_capped600,
          TRY_CAST(r.sf100k_eval_is_mate AS BOOLEAN) AS sf100k_eval_is_mate,
          TRY_CAST(r.sf100k_eval_mate_ply_disconnected AS DOUBLE)
            AS sf100k_eval_mate_ply_disconnected,
          CAST(r.sf100k_engine_fairness_bin AS VARCHAR) AS sf100k_engine_fairness_bin,
          TRY_CAST(r.sf100k_fair_subset_main AS BOOLEAN) AS sf100k_fair_subset_main,
          TRY_CAST(r.sf100k_clearly_worse_subset AS BOOLEAN) AS sf100k_clearly_worse_subset,
          TRY_CAST(r.sf100k_excluded_middle_subset AS BOOLEAN)
            AS sf100k_excluded_middle_subset,
          p.sf100k_source_part_id,
          p.sf100k_source_month,
          p.sf100k_source_block,
          CAST(r.filename AS VARCHAR) AS sf100k_source_path,
          {', '.join(optional)}
        FROM sf_raw AS r
        INNER JOIN sf_part_manifest AS p
          ON CAST(r.filename AS VARCHAR) = p.sf100k_source_path
        """
    )
    return stage05_path, stage06_path


def run_source_qa(
    connection: duckdb.DuckDBPyConnection,
    *,
    month: str,
    expected_rows: int,
) -> dict[str, Any]:
    stage05 = one_row_dict(
        connection,
        """
        SELECT
          COUNT(*)::BIGINT AS rows,
          COUNT(DISTINCT game_id)::BIGINT AS unique_game_ids,
          COUNT(*) FILTER (WHERE game_id IS NULL)::BIGINT AS null_game_ids,
          COUNT(*) FILTER (WHERE api_status IS DISTINCT FROM 'timeout')::BIGINT
            AS non_timeout_rows,
          COUNT(*) FILTER (WHERE api_rated IS DISTINCT FROM TRUE)::BIGINT AS non_rated_rows,
          COUNT(*) FILTER (WHERE lower(api_variant) IS DISTINCT FROM 'standard')::BIGINT
            AS nonstandard_rows,
          COUNT(*) FILTER (
            WHERE chooser_username_norm IS NULL OR trim(chooser_username_norm) = ''
          )::BIGINT AS missing_chooser_cluster_rows,
          COUNT(*) FILTER (
            WHERE timeout_draw IS NULL
               OR timeout_chooser_win IS NULL
               OR timeout_chooser_loss IS NULL
               OR chooser_has_mating_material IS NULL
               OR timeout_draw_no_mating_material IS NULL
               OR outcome_kind_draw IS NULL
          )::BIGINT AS null_outcome_component_rows,
          COUNT(*) FILTER (
            WHERE lower(chooser_color) NOT IN ('white', 'black')
               OR lower(disconnected_color) NOT IN ('white', 'black')
               OR lower(chooser_color) = lower(disconnected_color)
          )::BIGINT AS invalid_role_color_rows,
          COUNT(*) FILTER (
            WHERE lower(side_to_move_after_last) IS DISTINCT FROM lower(disconnected_color)
          )::BIGINT AS side_to_move_role_mismatch_rows,
          COUNT(*) FILTER (
            WHERE CAST(timeout_draw AS INTEGER)
                + CAST(timeout_chooser_win AS INTEGER)
                + CAST(timeout_chooser_loss AS INTEGER) <> 1
          )::BIGINT AS outcome_partition_mismatch_rows,
          COUNT(*) FILTER (
            WHERE outcome_kind_draw IS DISTINCT FROM (timeout_draw AND chooser_has_mating_material)
          )::BIGINT AS kind_definition_mismatch_rows,
          COUNT(*) FILTER (
            WHERE timeout_draw_no_mating_material
              IS DISTINCT FROM (timeout_draw AND NOT chooser_has_mating_material)
          )::BIGINT AS no_mating_draw_definition_mismatch_rows,
          SUM(CAST(outcome_kind_draw AS BIGINT))::BIGINT AS kind_draws,
          SUM(CAST(timeout_draw AS BIGINT))::BIGINT AS timeout_draws,
          SUM(CAST(timeout_chooser_win AS BIGINT))::BIGINT AS timeout_chooser_wins,
          SUM(CAST(timeout_chooser_loss AS BIGINT))::BIGINT AS timeout_chooser_losses
        FROM s05
        """,
    )
    if stage05["rows"] != expected_rows or stage05["unique_game_ids"] != expected_rows:
        raise RuntimeError(f"{month}: Stage 05 row/uniqueness contract failed: {stage05}")
    assert_zero_fields(
        f"{month} Stage 05",
        stage05,
        (
            "null_game_ids",
            "non_timeout_rows",
            "non_rated_rows",
            "nonstandard_rows",
            "missing_chooser_cluster_rows",
            "null_outcome_component_rows",
            "invalid_role_color_rows",
            "side_to_move_role_mismatch_rows",
            "outcome_partition_mismatch_rows",
            "kind_definition_mismatch_rows",
            "no_mating_draw_definition_mismatch_rows",
        ),
    )

    stage06 = one_row_dict(
        connection,
        """
        SELECT
          COUNT(*)::BIGINT AS rows,
          COUNT(DISTINCT game_id)::BIGINT AS unique_game_ids,
          COUNT(*) FILTER (WHERE game_id IS NULL)::BIGINT AS null_game_ids,
          COUNT(*) FILTER (
            WHERE chooser_draw_payoff_v2 IS NULL
               OR chooser_win_payoff_v2 IS NULL
               OR chooser_win_premium_v2 IS NULL
          )::BIGINT AS null_cost_rows,
          COUNT(*) FILTER (
            WHERE NOT isfinite(chooser_draw_payoff_v2)
               OR NOT isfinite(chooser_win_payoff_v2)
               OR NOT isfinite(chooser_win_premium_v2)
          )::BIGINT AS nonfinite_cost_rows,
          COUNT(*) FILTER (
            WHERE chooser_user_id IS NULL OR disconnected_user_id IS NULL
          )::BIGINT AS null_user_id_rows,
          COUNT(*) FILTER (
            WHERE favorable_draw_v2 IS NULL
               OR both_ratingdiff_null IS NULL
               OR hidden_state_update_applied IS NULL
               OR color_adv_applied IS NULL
          )::BIGINT AS null_state_flag_rows,
          COUNT(*) FILTER (
            WHERE ABS(chooser_win_premium_v2
                  - (chooser_win_payoff_v2 - chooser_draw_payoff_v2)) > 1e-9
          )::BIGINT AS win_premium_identity_failure_rows,
          COALESCE(MAX(ABS(chooser_win_premium_v2
              - (chooser_win_payoff_v2 - chooser_draw_payoff_v2))), 0)::DOUBLE
            AS max_abs_win_premium_identity_error,
          COUNT(*) FILTER (
            WHERE favorable_draw_v2 IS DISTINCT FROM (chooser_draw_payoff_v2 >= 0)
          )::BIGINT AS favorable_definition_mismatch_rows,
          COUNT(*) FILTER (
            WHERE both_ratingdiff_null AND hidden_state_update_applied
          )::BIGINT AS both_null_but_update_applied_rows,
          COUNT(*) FILTER (
            WHERE NOT both_ratingdiff_null AND NOT hidden_state_update_applied
          )::BIGINT AS non_both_null_but_update_skipped_rows,
          COUNT(*) FILTER (WHERE color_adv_applied)::BIGINT AS color_adv_rows,
          COUNT(*) FILTER (
            WHERE white_rating_source_match IS DISTINCT FROM TRUE
               OR black_rating_source_match IS DISTINCT FROM TRUE
               OR white_ratingdiff_source_match IS DISTINCT FROM TRUE
               OR black_ratingdiff_source_match IS DISTINCT FROM TRUE
               OR speed_source_match IS DISTINCT FROM TRUE
               OR month_source_match IS DISTINCT FROM TRUE
          )::BIGINT AS source_match_failure_rows,
          SUM(CAST(both_ratingdiff_null AS BIGINT))::BIGINT AS both_ratingdiff_null_rows
        FROM s06
        """,
    )
    if stage06["rows"] != expected_rows or stage06["unique_game_ids"] != expected_rows:
        raise RuntimeError(f"{month}: Stage 06 row/uniqueness contract failed: {stage06}")
    assert_zero_fields(
        f"{month} Stage 06",
        stage06,
        (
            "null_game_ids",
            "null_cost_rows",
            "nonfinite_cost_rows",
            "null_user_id_rows",
            "null_state_flag_rows",
            "win_premium_identity_failure_rows",
            "favorable_definition_mismatch_rows",
            "both_null_but_update_applied_rows",
            "non_both_null_but_update_skipped_rows",
            "color_adv_rows",
            "source_match_failure_rows",
        ),
    )

    stockfish = one_row_dict(
        connection,
        f"""
        SELECT
          COUNT(*)::BIGINT AS rows,
          COUNT(DISTINCT game_id)::BIGINT AS unique_game_ids,
          COUNT(*) FILTER (WHERE game_id IS NULL)::BIGINT AS null_game_ids,
          COUNT(*) FILTER (WHERE sf100k_ok IS DISTINCT FROM TRUE)::BIGINT AS non_ok_rows,
          COUNT(*) FILTER (
            WHERE sf100k_stockfish_name IS NULL OR trim(sf100k_stockfish_name) = ''
               OR sf100k_stockfish_sha256 IS NULL OR trim(sf100k_stockfish_sha256) = ''
               OR sf100k_threads IS NULL OR sf100k_threads <= 0
               OR sf100k_hash_mb IS NULL OR sf100k_hash_mb <= 0
          )::BIGINT AS missing_engine_identity_rows,
          COUNT(*) FILTER (
            WHERE sf100k_nodes_requested IS DISTINCT FROM 100000
          )::BIGINT AS requested_nodes_not_100000_rows,
          COUNT(*) FILTER (
            WHERE sf100k_nodes_searched IS NULL OR sf100k_nodes_searched <= 0
          )::BIGINT AS invalid_nodes_searched_rows,
          COUNT(*) FILTER (
            WHERE (sf100k_nodes_searched IS NULL OR sf100k_nodes_searched <= 0)
              AND NOT (
                sf100k_score_type_side_to_move = 'mate'
                AND sf100k_score_value_side_to_move = 0
              )
          )::BIGINT AS invalid_nodes_searched_unapproved_rows,
          COUNT(*) FILTER (
            WHERE sf100k_depth IS NULL OR sf100k_seldepth IS NULL
          )::BIGINT AS missing_depth_rows,
          COUNT(*) FILTER (
            WHERE (sf100k_depth IS NULL OR sf100k_seldepth IS NULL)
              AND NOT (
                sf100k_score_type_side_to_move = 'mate'
                AND sf100k_score_value_side_to_move = 0
              )
          )::BIGINT AS missing_depth_unapproved_rows,
          COUNT(*) FILTER (
            WHERE sf100k_eval_method IS DISTINCT FROM 'uci_go_nodes'
          )::BIGINT AS eval_method_mismatch_rows,
          COUNT(*) FILTER (
            WHERE sf100k_perspective_assumption IS DISTINCT FROM 'explicit_disconnected_color'
          )::BIGINT AS perspective_assumption_mismatch_rows,
          COUNT(*) FILTER (
            WHERE sf100k_fen_turn_matches_disconnected_color IS DISTINCT FROM TRUE
          )::BIGINT AS fen_turn_disconnected_mismatch_rows,
          COUNT(*) FILTER (
            WHERE sf100k_source_month IS DISTINCT FROM {sql_literal(month)}
               OR month IS DISTINCT FROM {sql_literal(month)}
          )::BIGINT AS source_month_mismatch_rows,
          COUNT(*) FILTER (
            WHERE sf100k_eval_cp_disconnected IS NULL
               OR sf100k_eval_cp_disconnected_raw IS NULL
               OR sf100k_eval_cp_disconnected_capped600 IS NULL
          )::BIGINT AS missing_eval_rows,
          COUNT(*) FILTER (
            WHERE sf100k_eval_cp_disconnected_raw
              IS DISTINCT FROM sf100k_eval_cp_disconnected
          )::BIGINT AS raw_eval_mismatch_rows,
          COUNT(*) FILTER (
            WHERE sf100k_eval_cp_disconnected_capped600
              IS DISTINCT FROM GREATEST(-600, LEAST(600, sf100k_eval_cp_disconnected))
          )::BIGINT AS capped_eval_mismatch_rows,
          COUNT(*) FILTER (
            WHERE sf100k_eval_is_mate
              IS DISTINCT FROM (sf100k_score_type_side_to_move = 'mate')
          )::BIGINT AS mate_type_mismatch_rows,
          COUNT(*) FILTER (
            WHERE sf100k_score_type_side_to_move NOT IN ('cp', 'mate')
          )::BIGINT AS invalid_score_type_rows,
          COUNT(*) FILTER (
            WHERE sf100k_score_type_side_to_move = 'cp'
              AND (
                sf100k_score_cp_side_to_move
                  IS DISTINCT FROM CAST(sf100k_score_value_side_to_move AS DOUBLE)
                OR sf100k_eval_cp_disconnected
                  IS DISTINCT FROM sf100k_score_value_side_to_move
                OR sf100k_mate_ply_side_to_move IS NOT NULL
                OR sf100k_eval_mate_ply_disconnected IS NOT NULL
              )
          )::BIGINT AS cp_score_consistency_failure_rows,
          COUNT(*) FILTER (
            WHERE sf100k_score_type_side_to_move = 'mate'
              AND (
                sf100k_score_cp_side_to_move IS NOT NULL
                OR sf100k_eval_cp_disconnected
                  IS DISTINCT FROM CASE
                    WHEN sf100k_score_value_side_to_move = 0 THEN -10000
                    ELSE 10000 * SIGN(sf100k_score_value_side_to_move)
                  END
                OR sf100k_mate_ply_side_to_move
                  IS DISTINCT FROM sf100k_eval_mate_ply_disconnected
              )
          )::BIGINT AS mate_score_consistency_failure_rows,
          COUNT(*) FILTER (
            WHERE sf100k_score_type_side_to_move = 'mate'
              AND sf100k_score_value_side_to_move = 0
          )::BIGINT AS terminal_mate_zero_rows,
          COUNT(*) FILTER (
            WHERE sf100k_engine_fairness_bin IS DISTINCT FROM ({FAIRNESS_BIN_SQL})
          )::BIGINT AS source_fairness_bin_mismatch_rows,
          COUNT(*) FILTER (
            WHERE sf100k_fair_subset_main
              IS DISTINCT FROM (sf100k_eval_cp_disconnected >= -100)
          )::BIGINT AS source_fair_subset_mismatch_rows,
          COUNT(*) FILTER (
            WHERE sf100k_clearly_worse_subset
              IS DISTINCT FROM (sf100k_eval_cp_disconnected <= -300)
          )::BIGINT AS source_clearly_worse_mismatch_rows,
          COUNT(*) FILTER (
            WHERE sf100k_excluded_middle_subset
              IS DISTINCT FROM (
                sf100k_eval_cp_disconnected > -300
                AND sf100k_eval_cp_disconnected < -100
              )
          )::BIGINT AS source_excluded_middle_mismatch_rows,
          COUNT(DISTINCT sf100k_stockfish_sha256)::BIGINT AS distinct_engine_hashes,
          COUNT(DISTINCT sf100k_stockfish_name)::BIGINT AS distinct_engine_names
        FROM sf
        """,
    )
    if stockfish["rows"] != expected_rows or stockfish["unique_game_ids"] != expected_rows:
        raise RuntimeError(f"{month}: Stockfish row/uniqueness contract failed: {stockfish}")
    terminal_mate_zero_qa = validate_terminal_mate_zero_rows(connection, month=month)
    if terminal_mate_zero_qa["validated_rows"] != stockfish["terminal_mate_zero_rows"]:
        raise RuntimeError(
            f"{month}: terminal Mate(0) count changed between SQL and FEN validation: "
            f"SQL={stockfish['terminal_mate_zero_rows']}, "
            f"validated={terminal_mate_zero_qa['validated_rows']}"
        )
    stockfish["terminal_mate_zero_qa"] = terminal_mate_zero_qa
    assert_zero_fields(
        f"{month} Stockfish",
        stockfish,
        (
            "null_game_ids",
            "non_ok_rows",
            "missing_engine_identity_rows",
            "requested_nodes_not_100000_rows",
            "invalid_nodes_searched_unapproved_rows",
            "missing_depth_unapproved_rows",
            "eval_method_mismatch_rows",
            "perspective_assumption_mismatch_rows",
            "fen_turn_disconnected_mismatch_rows",
            "source_month_mismatch_rows",
            "missing_eval_rows",
            "raw_eval_mismatch_rows",
            "capped_eval_mismatch_rows",
            "mate_type_mismatch_rows",
            "invalid_score_type_rows",
            "cp_score_consistency_failure_rows",
            "mate_score_consistency_failure_rows",
            "source_fairness_bin_mismatch_rows",
            "source_fair_subset_mismatch_rows",
            "source_clearly_worse_mismatch_rows",
            "source_excluded_middle_mismatch_rows",
        ),
    )
    if stockfish["distinct_engine_hashes"] != 1:
        raise RuntimeError(
            f"{month}: expected exactly one Stockfish binary hash; "
            f"observed {stockfish['distinct_engine_hashes']}"
        )
    if stockfish["distinct_engine_names"] != 1:
        raise RuntimeError(
            f"{month}: expected exactly one Stockfish engine name; "
            f"observed {stockfish['distinct_engine_names']}"
        )

    joins = one_row_dict(
        connection,
        """
        SELECT
          (SELECT COUNT(*) FROM s05 LEFT JOIN s06 ON s05.game_id = s06.game_id
             WHERE s06.game_id IS NULL)::BIGINT AS missing_stage06_from_stage05,
          (SELECT COUNT(*) FROM s06 LEFT JOIN s05 ON s06.game_id = s05.game_id
             WHERE s05.game_id IS NULL)::BIGINT AS extra_stage06_not_stage05,
          (SELECT COUNT(*) FROM s05 LEFT JOIN sf ON s05.game_id = sf.game_id
             WHERE sf.game_id IS NULL)::BIGINT AS missing_sf_from_stage05,
          (SELECT COUNT(*) FROM sf LEFT JOIN s05 ON sf.game_id = s05.game_id
             WHERE s05.game_id IS NULL)::BIGINT AS extra_sf_not_stage05
        """,
    )
    assert_zero_fields(
        f"{month} set equality",
        joins,
        (
            "missing_stage06_from_stage05",
            "extra_stage06_not_stage05",
            "missing_sf_from_stage05",
            "extra_sf_not_stage05",
        ),
    )

    cross_source = one_row_dict(
        connection,
        """
        SELECT
          COUNT(*)::BIGINT AS joined_rows,
          COUNT(*) FILTER (WHERE s05.month IS DISTINCT FROM s06.month)::BIGINT
            AS stage06_month_mismatch_rows,
          COUNT(*) FILTER (WHERE s05.api_speed IS DISTINCT FROM s06.api_speed)::BIGINT
            AS stage06_speed_mismatch_rows,
          COUNT(*) FILTER (WHERE s05.api_perf IS DISTINCT FROM s06.api_perf)::BIGINT
            AS stage06_perf_mismatch_rows,
          COUNT(*) FILTER (
            WHERE s05.api_created_at_ms IS DISTINCT FROM s06.api_created_at_ms
          )::BIGINT AS stage06_created_at_mismatch_rows,
          COUNT(*) FILTER (WHERE s05.chooser_color IS DISTINCT FROM s06.chooser_color)::BIGINT
            AS stage06_chooser_color_mismatch_rows,
          COUNT(*) FILTER (
            WHERE s05.disconnected_color IS DISTINCT FROM s06.disconnected_color
          )::BIGINT AS stage06_disconnected_color_mismatch_rows,
          COUNT(*) FILTER (WHERE s05.chooser_elo IS DISTINCT FROM s06.chooser_elo)::BIGINT
            AS stage06_chooser_elo_mismatch_rows,
          COUNT(*) FILTER (
            WHERE s05.disconnected_elo IS DISTINCT FROM s06.disconnected_elo
          )::BIGINT AS stage06_disconnected_elo_mismatch_rows,
          COUNT(*) FILTER (
            WHERE s05.white_elo_pgn IS DISTINCT FROM s06.white_elo_pgn
               OR s05.black_elo_pgn IS DISTINCT FROM s06.black_elo_pgn
               OR s05.white_rating_diff_pgn IS DISTINCT FROM s06.white_rating_diff_pgn
               OR s05.black_rating_diff_pgn IS DISTINCT FROM s06.black_rating_diff_pgn
          )::BIGINT AS stage06_pgn_rating_source_mismatch_rows,
          COUNT(*) FILTER (WHERE s05.month IS DISTINCT FROM sf.month)::BIGINT
            AS sf_month_mismatch_rows,
          COUNT(*) FILTER (
            WHERE s05.fen_after_last_move IS DISTINCT FROM sf.fen_after_last_move
          )::BIGINT AS sf_fen_mismatch_rows,
          COUNT(*) FILTER (
            WHERE lower(s05.side_to_move_after_last)
              IS DISTINCT FROM lower(sf.side_to_move_after_last)
          )::BIGINT AS sf_side_to_move_mismatch_rows,
          COUNT(*) FILTER (
            WHERE lower(s05.disconnected_color)
              IS DISTINCT FROM lower(sf.sf100k_disconnected_color_for_perspective)
          )::BIGINT AS sf_disconnected_perspective_color_mismatch_rows,
          COUNT(*) FILTER (
            WHERE lower(s05.side_to_move_after_last)
              IS DISTINCT FROM lower(sf.sf100k_fen_turn_color)
          )::BIGINT AS sf_fen_turn_color_mismatch_rows,
          COUNT(*) FILTER (
            WHERE sf.sf_api_status IS NOT NULL
              AND s05.api_status IS DISTINCT FROM sf.sf_api_status
          )::BIGINT AS sf_optional_api_status_mismatch_rows,
          COUNT(*) FILTER (
            WHERE sf.sf_api_speed IS NOT NULL
              AND s05.api_speed IS DISTINCT FROM sf.sf_api_speed
          )::BIGINT AS sf_optional_speed_mismatch_rows,
          COUNT(*) FILTER (
            WHERE sf.sf_outcome_kind_draw IS NOT NULL
              AND s05.outcome_kind_draw IS DISTINCT FROM sf.sf_outcome_kind_draw
          )::BIGINT AS sf_duplicate_kind_diagnostic_mismatch_rows,
          COUNT(*) FILTER (
            WHERE sf.sf_timeout_draw IS NOT NULL
              AND s05.timeout_draw IS DISTINCT FROM sf.sf_timeout_draw
          )::BIGINT AS sf_duplicate_timeout_draw_diagnostic_mismatch_rows,
          COUNT(*) FILTER (
            WHERE sf.sf_chooser_has_mating_material IS NOT NULL
              AND s05.chooser_has_mating_material
                IS DISTINCT FROM sf.sf_chooser_has_mating_material
          )::BIGINT AS sf_duplicate_mating_diagnostic_mismatch_rows
        FROM s05
        INNER JOIN s06 ON s05.game_id = s06.game_id
        INNER JOIN sf ON s05.game_id = sf.game_id
        """,
    )
    if cross_source["joined_rows"] != expected_rows:
        raise RuntimeError(f"{month}: joined source rows changed: {cross_source}")
    optional_duplicate_details = collect_optional_sf_duplicate_details(
        connection,
        mismatch_counts=cross_source,
    )
    cross_source["optional_stockfish_duplicate_details"] = optional_duplicate_details
    assert_zero_fields(
        f"{month} authoritative cross-source consistency",
        cross_source,
        (
            "stage06_month_mismatch_rows",
            "stage06_speed_mismatch_rows",
            "stage06_perf_mismatch_rows",
            "stage06_created_at_mismatch_rows",
            "stage06_chooser_color_mismatch_rows",
            "stage06_disconnected_color_mismatch_rows",
            "stage06_chooser_elo_mismatch_rows",
            "stage06_disconnected_elo_mismatch_rows",
            "stage06_pgn_rating_source_mismatch_rows",
            "sf_month_mismatch_rows",
            "sf_fen_mismatch_rows",
            "sf_side_to_move_mismatch_rows",
            "sf_disconnected_perspective_color_mismatch_rows",
            "sf_fen_turn_color_mismatch_rows",
        ),
    )

    return {
        "stage05": stage05,
        "stage06": stage06,
        "stockfish": stockfish,
        "set_equality": joins,
        "cross_source": cross_source,
    }


def output_select_sql() -> str:
    selections = [
        f"s05.{quote_identifier(source)} AS {quote_identifier(alias)}"
        for source, alias in STAGE05_COLUMNS
    ]
    selections.extend(
        f"s06.{quote_identifier(name)} AS {quote_identifier(name)}"
        for name in STAGE06_COLUMNS
    )
    selections.extend(
        [
            "sf.sf100k_source_block AS sf100k_source_block",
            "CAST(sf.sf100k_source_part_id AS SMALLINT) AS sf100k_source_part_id",
            "sf.sf100k_stockfish_name AS sf100k_stockfish_name",
            "sf.sf100k_stockfish_sha256 AS sf100k_stockfish_sha256",
            "sf.sf100k_nodes_requested AS sf100k_nodes_requested",
            "sf.sf100k_nodes_searched AS sf100k_nodes_searched",
            "sf.sf100k_threads AS sf100k_threads",
            "sf.sf100k_hash_mb AS sf100k_hash_mb",
            "sf.sf100k_depth AS sf100k_depth",
            "sf.sf100k_seldepth AS sf100k_seldepth",
            "sf.sf100k_eval_method AS sf100k_eval_method",
            "sf.sf100k_fen_turn_color AS sf100k_fen_turn_color",
            (
                "sf.sf100k_disconnected_color_for_perspective "
                "AS sf100k_disconnected_color_for_perspective"
            ),
            "sf.sf100k_perspective_assumption AS sf100k_perspective_assumption",
            (
                "sf.sf100k_fen_turn_matches_disconnected_color "
                "AS sf100k_fen_turn_matches_disconnected_color"
            ),
            "sf.sf100k_score_type_side_to_move AS sf100k_score_type_side_to_move",
            "sf.sf100k_score_value_side_to_move AS sf100k_score_value_side_to_move",
            "sf.sf100k_score_cp_side_to_move AS sf100k_score_cp_side_to_move",
            "sf.sf100k_mate_ply_side_to_move AS sf100k_mate_ply_side_to_move",
            (
                "CAST(sf.sf100k_eval_cp_disconnected_raw AS INTEGER) "
                "AS engine_eval_cp_disconnected_raw"
            ),
            (
                "CAST(sf.sf100k_eval_cp_disconnected AS INTEGER) "
                "AS engine_eval_cp_disconnected"
            ),
            (
                "CAST(sf.sf100k_eval_cp_disconnected_capped600 AS SMALLINT) "
                "AS engine_eval_cp_disconnected_capped600"
            ),
            (
                "CAST(sf.sf100k_eval_cp_disconnected_capped600 AS DOUBLE) / 100.0 "
                "AS engine_eval_hundreds_capped600"
            ),
            "sf.sf100k_eval_is_mate AS engine_eval_is_mate",
            "sf.sf100k_eval_mate_ply_disconnected AS engine_eval_mate_ply_disconnected",
            f"({FAIRNESS_BIN_SQL}) AS engine_fairness_bin",
            (
                "CASE "
                "WHEN sf.sf100k_eval_cp_disconnected >= -100 THEN 'fair_competitive' "
                "WHEN sf.sf100k_eval_cp_disconnected <= -300 THEN 'clearly_worse' "
                "ELSE 'excluded_middle' END AS fairness_region"
            ),
            "(sf.sf100k_eval_cp_disconnected >= -100) AS fair_competitive",
            "(sf.sf100k_eval_cp_disconnected <= -300) AS clearly_worse",
            (
                "(sf.sf100k_eval_cp_disconnected > -300 "
                " AND sf.sf100k_eval_cp_disconnected < -100) AS excluded_middle"
            ),
            "s05.outcome_kind_draw AS kind_draw",
            "(s06.chooser_draw_payoff_v2 >= 0) AS draw_nonnegative",
            "(s06.chooser_draw_payoff_v2 > 0) AS draw_strict_positive",
            "(s06.chooser_draw_payoff_v2 < 0) AS draw_costly",
        ]
    )
    return (
        "SELECT\n  "
        + ",\n  ".join(selections)
        + "\nFROM s05\n"
        + "INNER JOIN s06 ON s05.game_id = s06.game_id\n"
        + "INNER JOIN sf ON s05.game_id = sf.game_id\n"
        + "ORDER BY s05.game_id"
    )


def validate_written_output(
    connection: duckdb.DuckDBPyConnection,
    *,
    path: Path,
    month: str,
    expected_rows: int,
    expected_columns: Sequence[str],
    source_qa: dict[str, Any],
) -> tuple[dict[str, Any], pa.Schema]:
    parquet = pq.ParquetFile(path)
    schema = parquet.schema_arrow
    actual_columns = schema.names
    if list(actual_columns) != list(expected_columns):
        expected_set = set(expected_columns)
        actual_set = set(actual_columns)
        raise RuntimeError(
            f"{month}: output schema contract mismatch\n"
            f"missing={sorted(expected_set - actual_set)}\n"
            f"extra={sorted(actual_set - expected_set)}\n"
            f"order_match={list(actual_columns) == list(expected_columns)}"
        )
    if parquet.metadata.num_rows != expected_rows:
        raise RuntimeError(
            f"{month}: output footer has {parquet.metadata.num_rows} rows, expected {expected_rows}"
        )

    output = one_row_dict(
        connection,
        f"""
        SELECT
          COUNT(*)::BIGINT AS rows,
          COUNT(DISTINCT game_id)::BIGINT AS unique_game_ids,
          COUNT(*) FILTER (WHERE game_id IS NULL)::BIGINT AS null_game_ids,
          COUNT(DISTINCT month)::BIGINT AS distinct_month_values,
          COUNT(*) FILTER (WHERE month IS DISTINCT FROM {sql_literal(month)})::BIGINT
            AS wrong_month_rows,
          COUNT(*) FILTER (
            WHERE kind_draw IS DISTINCT FROM outcome_kind_draw
          )::BIGINT AS kind_alias_mismatch_rows,
          COUNT(*) FILTER (
            WHERE draw_nonnegative IS DISTINCT FROM (chooser_draw_payoff_v2 >= 0)
               OR draw_strict_positive IS DISTINCT FROM (chooser_draw_payoff_v2 > 0)
               OR draw_costly IS DISTINCT FROM (chooser_draw_payoff_v2 < 0)
               OR CAST(draw_nonnegative AS INTEGER) + CAST(draw_costly AS INTEGER) <> 1
          )::BIGINT AS price_indicator_mismatch_rows,
          COUNT(*) FILTER (
            WHERE favorable_draw_v2 IS DISTINCT FROM draw_nonnegative
          )::BIGINT AS stage06_favorable_alias_mismatch_rows,
          COUNT(*) FILTER (
            WHERE CAST(fair_competitive AS INTEGER)
                + CAST(clearly_worse AS INTEGER)
                + CAST(excluded_middle AS INTEGER) <> 1
          )::BIGINT AS fairness_partition_mismatch_rows,
          COUNT(*) FILTER (
            WHERE fair_competitive IS DISTINCT FROM (engine_eval_cp_disconnected >= -100)
               OR clearly_worse IS DISTINCT FROM (engine_eval_cp_disconnected <= -300)
               OR excluded_middle IS DISTINCT FROM (
                    engine_eval_cp_disconnected > -300
                    AND engine_eval_cp_disconnected < -100
                  )
          )::BIGINT AS fairness_indicator_mismatch_rows,
          COUNT(*) FILTER (
            WHERE engine_eval_cp_disconnected_capped600
              IS DISTINCT FROM GREATEST(-600, LEAST(600, engine_eval_cp_disconnected))
               OR engine_eval_hundreds_capped600
              IS DISTINCT FROM CAST(engine_eval_cp_disconnected_capped600 AS DOUBLE) / 100.0
          )::BIGINT AS capped_eval_alias_mismatch_rows,
          COUNT(*) FILTER (
            WHERE engine_fairness_bin IS DISTINCT FROM
              CASE
                WHEN engine_eval_cp_disconnected >= 300 THEN 'disconnected_clearly_better'
                WHEN engine_eval_cp_disconnected > 100 THEN 'disconnected_better'
                WHEN engine_eval_cp_disconnected >= -100 THEN 'roughly_equal'
                WHEN engine_eval_cp_disconnected > -300 THEN 'modestly_worse_excluded'
                ELSE 'clearly_worse'
              END
          )::BIGINT AS fairness_bin_mismatch_rows,
          COUNT(*) FILTER (
            WHERE fairness_region IS DISTINCT FROM
              CASE
                WHEN engine_eval_cp_disconnected >= -100 THEN 'fair_competitive'
                WHEN engine_eval_cp_disconnected <= -300 THEN 'clearly_worse'
                ELSE 'excluded_middle'
              END
          )::BIGINT AS fairness_region_mismatch_rows,
          COUNT(*) FILTER (WHERE sf100k_nodes_requested IS DISTINCT FROM 100000)::BIGINT
            AS requested_nodes_mismatch_rows,
          COUNT(*) FILTER (
            WHERE color_adv_applied
          )::BIGINT AS color_adv_rows,
          COUNT(*) FILTER (
            WHERE chooser_draw_payoff_v2 IS NULL
               OR chooser_win_payoff_v2 IS NULL
               OR chooser_win_premium_v2 IS NULL
               OR engine_eval_cp_disconnected IS NULL
          )::BIGINT AS null_core_analysis_rows,
          COUNT(*) FILTER (
            WHERE NOT isfinite(chooser_draw_payoff_v2)
               OR NOT isfinite(chooser_win_payoff_v2)
               OR NOT isfinite(chooser_win_premium_v2)
          )::BIGINT AS nonfinite_core_analysis_rows,
          COUNT(*) FILTER (
            WHERE chooser_username_norm IS NULL OR trim(chooser_username_norm) = ''
          )::BIGINT AS missing_chooser_cluster_rows,
          SUM(CAST(kind_draw AS BIGINT))::BIGINT AS kind_draws,
          SUM(CAST(timeout_chooser_loss AS BIGINT))::BIGINT AS timeout_chooser_losses,
          SUM(CAST(both_ratingdiff_null AS BIGINT))::BIGINT AS both_ratingdiff_null_rows,
          SUM(CAST(fair_competitive AS BIGINT))::BIGINT AS fair_rows,
          SUM(CAST(clearly_worse AS BIGINT))::BIGINT AS clearly_worse_rows,
          SUM(CAST(excluded_middle AS BIGINT))::BIGINT AS excluded_middle_rows,
          SUM(CAST(draw_nonnegative AS BIGINT))::BIGINT AS draw_nonnegative_rows,
          SUM(CAST(draw_strict_positive AS BIGINT))::BIGINT AS draw_strict_positive_rows,
          SUM(CAST(draw_costly AS BIGINT))::BIGINT AS draw_costly_rows
        FROM read_parquet({sql_literal(path)})
        """,
    )
    if output["rows"] != expected_rows or output["unique_game_ids"] != expected_rows:
        raise RuntimeError(f"{month}: written output row/uniqueness failure: {output}")
    if output["kind_draws"] != source_qa["stage05"]["kind_draws"]:
        raise RuntimeError(f"{month}: output kind-draw total differs from Stage 05 authority")
    if output["timeout_chooser_losses"] != source_qa["stage05"]["timeout_chooser_losses"]:
        raise RuntimeError(f"{month}: output chooser-loss total differs from Stage 05 authority")
    if output["both_ratingdiff_null_rows"] != source_qa["stage06"]["both_ratingdiff_null_rows"]:
        raise RuntimeError(f"{month}: output both-null total differs from Stage 06 authority")
    assert_zero_fields(
        f"{month} written output",
        output,
        (
            "null_game_ids",
            "wrong_month_rows",
            "kind_alias_mismatch_rows",
            "price_indicator_mismatch_rows",
            "stage06_favorable_alias_mismatch_rows",
            "fairness_partition_mismatch_rows",
            "fairness_indicator_mismatch_rows",
            "capped_eval_alias_mismatch_rows",
            "fairness_bin_mismatch_rows",
            "fairness_region_mismatch_rows",
            "requested_nodes_mismatch_rows",
            "color_adv_rows",
            "null_core_analysis_rows",
            "nonfinite_core_analysis_rows",
            "missing_chooser_cluster_rows",
        ),
    )
    if output["distinct_month_values"] != 1:
        raise RuntimeError(f"{month}: output contains multiple month values")
    return output, schema


def verify_existing_month_receipt(
    *,
    month: str,
    final_path: Path,
    receipt_path: Path,
    script_sha256: str,
    authority_sha256: dict[str, str],
) -> dict[str, Any]:
    if not receipt_path.is_file():
        raise RuntimeError(f"Existing month lacks _SUCCESS.json: {receipt_path}")
    if not final_path.is_file():
        raise RuntimeError(f"Existing month receipt lacks analysis panel: {final_path}")
    receipt = json.loads(receipt_path.read_text(encoding="utf-8"))
    checks = [
        (receipt.get("final_ok") is True, "final_ok is not true"),
        (receipt.get("month") == month, "month differs"),
        (receipt.get("script_sha256") == script_sha256, "producer script hash differs"),
        (
            receipt.get("authority_sha256") == authority_sha256,
            "frozen authority hash map differs",
        ),
        (receipt.get("output_rows") == MONTH_ROWS[month], "output row count differs"),
    ]
    failures = [message for ok, message in checks if not ok]
    if failures:
        raise RuntimeError(
            f"Existing {month} receipt cannot be resumed safely: " + "; ".join(failures)
        )
    actual_hash = sha256_file(final_path)
    if receipt.get("output_sha256") != actual_hash:
        raise RuntimeError(
            f"Existing {month} output hash changed: receipt={receipt.get('output_sha256')} "
            f"actual={actual_hash}"
        )
    return receipt


def build_month(
    *,
    month: str,
    parts: Sequence[SfPart],
    output_root: Path,
    temp_root: Path,
    threads: int,
    memory_limit: str,
    contract: dict[str, Any],
    authority_sha256: dict[str, str],
    git_state: dict[str, Any],
    logger: RunLogger,
) -> dict[str, Any]:
    expected_rows = MONTH_ROWS[month]
    month_dir = output_root / f"month={month}"
    final_path = month_dir / "analysis_panel.parquet"
    receipt_path = month_dir / "_SUCCESS.json"
    script_sha256 = contract["script_sha256"]

    if receipt_path.exists() or final_path.exists():
        logger(f"{month}: verifying existing monthly product for safe resume")
        receipt = verify_existing_month_receipt(
            month=month,
            final_path=final_path,
            receipt_path=receipt_path,
            script_sha256=script_sha256,
            authority_sha256=authority_sha256,
        )
        logger(f"{month}: RESUME_OK; existing output hash and receipt match")
        return receipt

    month_dir.mkdir(parents=True, exist_ok=True)
    stale_temps = sorted(month_dir.glob("analysis_panel.parquet.tmp.*"))
    if stale_temps:
        logger(
            f"{month}: preserving {len(stale_temps)} prior temporary file(s); "
            "a new unique temporary name will be used"
        )
    temp_path = month_dir / f"analysis_panel.parquet.tmp.{uuid.uuid4().hex}"
    month_parts = [part for part in parts if part.month == month]
    if not month_parts:
        raise RuntimeError(f"No certified Stockfish parts for {month}")

    database = duckdb.connect(database=":memory:")
    configure_duckdb(
        database,
        threads=threads,
        memory_limit=memory_limit,
        temp_directory=temp_root / f"month={month}",
    )
    started = time.time()
    try:
        logger(
            f"{month}: creating read-only source views; expected_rows={expected_rows:,}; "
            f"sf_parts={len(month_parts)}"
        )
        stage05_path, stage06_path = create_month_views(
            database, month=month, parts=month_parts
        )

        qa_started = time.time()
        source_qa = run_source_qa(database, month=month, expected_rows=expected_rows)
        qa_seconds = time.time() - qa_started
        logger(f"{month}: SOURCE_QA_OK in {qa_seconds:,.1f}s")

        select_sql = output_select_sql()
        copy_started = time.time()
        logger(f"{month}: writing deterministic game_id-sorted temporary Parquet")
        database.execute(
            f"""
            COPY ({select_sql})
            TO {sql_literal(temp_path)}
            (FORMAT PARQUET, COMPRESSION ZSTD, ROW_GROUP_SIZE 250000)
            """
        )
        copy_seconds = time.time() - copy_started
        logger(f"{month}: Parquet write completed in {copy_seconds:,.1f}s")

        output_qa_started = time.time()
        output_qa, output_schema = validate_written_output(
            database,
            path=temp_path,
            month=month,
            expected_rows=expected_rows,
            expected_columns=contract["output_columns"],
            source_qa=source_qa,
        )
        output_sha256 = sha256_file(temp_path)
        output_qa_seconds = time.time() - output_qa_started
        logger(f"{month}: OUTPUT_QA_OK in {output_qa_seconds:,.1f}s")

        os.replace(temp_path, final_path)
        elapsed = time.time() - started
        receipt = {
            "final_ok": True,
            "status": "STAGE07_MONTH_CERTIFIED_OK",
            "month": month,
            "created_at": utc_now(),
            "script_version": SCRIPT_VERSION,
            "script_sha256": script_sha256,
            "git_head": git_state["head"],
            "authority_sha256": authority_sha256,
            "stage05_path": str(stage05_path),
            "stage06_path": str(stage06_path),
            "sf100k_part_ids": [part.part_id for part in month_parts],
            "sf100k_paths": [str(part.path) for part in month_parts],
            "sf100k_source_blocks": sorted({part.block for part in month_parts}),
            "output_path": str(final_path),
            "output_rows": expected_rows,
            "output_size_bytes": final_path.stat().st_size,
            "output_sha256": output_sha256,
            "output_schema": [
                {
                    "name": field.name,
                    "type": str(field.type),
                    "nullable": bool(field.nullable),
                }
                for field in output_schema
            ],
            "source_qa": source_qa,
            "output_qa": output_qa,
            "runtime_seconds": elapsed,
            "source_qa_seconds": qa_seconds,
            "copy_seconds": copy_seconds,
            "output_qa_seconds": output_qa_seconds,
        }
        atomic_write_json(receipt_path, receipt)
        logger(
            f"{month}: STAGE07_MONTH_CERTIFIED_OK rows={expected_rows:,} "
            f"sha256={output_sha256} elapsed={elapsed:,.1f}s"
        )
        return receipt
    finally:
        database.close()


def write_csv_rows(path: Path, rows: Sequence[dict[str, Any]], fieldnames: Sequence[str]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temp = path.with_name(path.name + f".tmp.{uuid.uuid4().hex}")
    with temp.open("w", encoding="utf-8", newline="") as stream:
        writer = csv.DictWriter(stream, fieldnames=list(fieldnames), extrasaction="ignore")
        writer.writeheader()
        for row in rows:
            writer.writerow({key: jsonable(value) for key, value in row.items()})
    os.replace(temp, path)


def write_execution_manifests(
    *,
    run_root: Path,
    output_root: Path,
    months: Sequence[str],
    parts: Sequence[SfPart],
    inventory: dict[str, dict[str, Any]],
    contract: dict[str, Any],
    authority_sha256: dict[str, str],
    git_state: dict[str, Any],
    args: argparse.Namespace,
) -> None:
    run_root.mkdir(parents=True, exist_ok=False)
    atomic_write_json(
        run_root / "command.json",
        {
            "created_at": utc_now(),
            "argv": sys.argv,
            "cwd": str(Path.cwd()),
            "python": sys.executable,
            "python_version": sys.version,
            "duckdb_version": duckdb.__version__,
            "pyarrow_version": pa.__version__,
            "output_root": str(output_root),
            "months": list(months),
            "threads": args.threads,
            "memory_limit": args.memory_limit,
            "temp_root": str(args.temp_root),
        },
    )
    atomic_write_json(run_root / "schema_contract.json", contract)
    atomic_write_json(run_root / "authority_sha256.json", authority_sha256)
    atomic_write_json(run_root / "git_state.json", git_state)
    atomic_write_json(
        run_root / "selected_month_input_inventory.json",
        {month: inventory[month] for month in months},
    )
    atomic_write_text(
        run_root / "input_stage05_paths_selected.txt",
        "".join(f"{inventory[month]['stage05_path']}\n" for month in months),
    )
    atomic_write_text(
        run_root / "input_stage06_paths_selected.txt",
        "".join(f"{inventory[month]['stage06_path']}\n" for month in months),
    )
    selected_months = set(months)
    atomic_write_text(
        run_root / "input_sf100k_paths_selected.txt",
        "".join(f"{part.path}\n" for part in parts if part.month in selected_months),
    )
    authority_snapshots = (
        (STAGE05_SUMMARY, "stage05_latest_summary.json"),
        (STAGE05_SUCCESS, "stage05_SUCCESS.json"),
        (STAGE06_SUMMARY, "stage06_latest_summary.json"),
        (STAGE06_SUCCESS, "stage06_SUCCESS.json"),
        (SF_CERT, "stockfish100k_CERTIFIED.json"),
    )
    for source, destination_name in authority_snapshots:
        shutil.copy2(source, run_root / destination_name)
    shutil.copy2(SF_PATH_LIST, run_root / "sf100k_full_24m_parquet_paths_AUTHENTICATED.txt")

    part_rows = [
        {
            "part_id": part.part_id,
            "month": part.month,
            "block": part.block,
            "rows": part.rows,
            "size_bytes": part.size_bytes,
            "path": str(part.path),
        }
        for part in parts
    ]
    write_csv_rows(
        run_root / "sf100k_part_manifest.csv",
        part_rows,
        ("part_id", "month", "block", "rows", "size_bytes", "path"),
    )


def finalize_global(
    *,
    output_root: Path,
    temp_root: Path,
    threads: int,
    memory_limit: str,
    receipts: Sequence[dict[str, Any]],
    contract: dict[str, Any],
    authority_sha256: dict[str, str],
    git_state: dict[str, Any],
    logger: RunLogger,
) -> dict[str, Any]:
    if tuple(receipt["month"] for receipt in receipts) != MONTHS:
        raise RuntimeError("Global finalization requires all 24 months in canonical order")
    output_paths = [Path(receipt["output_path"]) for receipt in receipts]
    if any(not path.is_file() for path in output_paths):
        raise RuntimeError("Global finalization found a missing monthly output")
    signatures = {schema_signature(pq.ParquetFile(path).schema_arrow) for path in output_paths}
    if len(signatures) != 1:
        raise RuntimeError(f"Monthly Stage 07 outputs have {len(signatures)} exact schemas")

    paths_sql = ", ".join(sql_literal(path) for path in output_paths)
    database = duckdb.connect(database=":memory:")
    configure_duckdb(
        database,
        threads=threads,
        memory_limit=memory_limit,
        temp_directory=temp_root / "global_finalization",
    )
    started = time.time()
    logger("GLOBAL: scanning 24 outputs for cross-month uniqueness and frozen totals")
    try:
        global_qa = one_row_dict(
            database,
            f"""
            SELECT
              COUNT(*)::BIGINT AS rows,
              COUNT(DISTINCT game_id)::BIGINT AS unique_game_ids,
              COUNT(DISTINCT month)::BIGINT AS months,
              COUNT(*) FILTER (WHERE game_id IS NULL)::BIGINT AS null_game_ids,
              SUM(CAST(kind_draw AS BIGINT))::BIGINT AS kind_draws,
              SUM(CAST(timeout_chooser_loss AS BIGINT))::BIGINT AS timeout_chooser_losses,
              SUM(CAST(both_ratingdiff_null AS BIGINT))::BIGINT AS both_ratingdiff_null_rows,
              COUNT(*) FILTER (WHERE color_adv_applied)::BIGINT AS color_adv_rows,
              COUNT(*) FILTER (
                WHERE sf100k_nodes_requested IS DISTINCT FROM 100000
              )::BIGINT AS requested_nodes_mismatch_rows,
              COUNT(*) FILTER (
                WHERE chooser_draw_payoff_v2 IS NULL
                   OR chooser_win_payoff_v2 IS NULL
                   OR chooser_win_premium_v2 IS NULL
                   OR engine_eval_cp_disconnected IS NULL
              )::BIGINT AS null_core_analysis_rows,
              COUNT(*) FILTER (
                WHERE NOT isfinite(chooser_draw_payoff_v2)
                   OR NOT isfinite(chooser_win_payoff_v2)
                   OR NOT isfinite(chooser_win_premium_v2)
              )::BIGINT AS nonfinite_core_analysis_rows,
              COUNT(*) FILTER (
                WHERE chooser_username_norm IS NULL OR trim(chooser_username_norm) = ''
              )::BIGINT AS missing_chooser_cluster_rows,
              COUNT(*) FILTER (
                WHERE favorable_draw_v2 IS DISTINCT FROM draw_nonnegative
              )::BIGINT AS favorable_definition_mismatch_rows,
              COUNT(*) FILTER (
                WHERE kind_draw IS DISTINCT FROM outcome_kind_draw
              )::BIGINT AS kind_alias_mismatch_rows,
              COUNT(*) FILTER (
                WHERE CAST(fair_competitive AS INTEGER)
                    + CAST(clearly_worse AS INTEGER)
                    + CAST(excluded_middle AS INTEGER) <> 1
              )::BIGINT AS fairness_partition_mismatch_rows,
              SUM(CAST(fair_competitive AS BIGINT))::BIGINT AS fair_rows,
              SUM(CAST(clearly_worse AS BIGINT))::BIGINT AS clearly_worse_rows,
              SUM(CAST(excluded_middle AS BIGINT))::BIGINT AS excluded_middle_rows,
              SUM(CAST(draw_nonnegative AS BIGINT))::BIGINT AS draw_nonnegative_rows,
              SUM(CAST(draw_strict_positive AS BIGINT))::BIGINT AS draw_strict_positive_rows,
              SUM(CAST(draw_costly AS BIGINT))::BIGINT AS draw_costly_rows
            FROM read_parquet([{paths_sql}], union_by_name=true)
            """,
        )
    finally:
        database.close()

    expected_exact = {
        "rows": EXPECTED_ROWS,
        "unique_game_ids": EXPECTED_ROWS,
        "months": 24,
        "kind_draws": EXPECTED_KIND_DRAWS,
        "timeout_chooser_losses": EXPECTED_CHOOSER_LOSSES,
        "both_ratingdiff_null_rows": EXPECTED_BOTH_RATINGDIFF_NULL,
    }
    mismatches = [
        f"{key}: expected={expected}, actual={global_qa.get(key)}"
        for key, expected in expected_exact.items()
        if global_qa.get(key) != expected
    ]
    if mismatches:
        raise RuntimeError("Global frozen-total mismatch:\n" + "\n".join(mismatches))
    assert_zero_fields(
        "Global Stage 07",
        global_qa,
        (
            "null_game_ids",
            "color_adv_rows",
            "requested_nodes_mismatch_rows",
            "null_core_analysis_rows",
            "nonfinite_core_analysis_rows",
            "missing_chooser_cluster_rows",
            "favorable_definition_mismatch_rows",
            "kind_alias_mismatch_rows",
            "fairness_partition_mismatch_rows",
        ),
    )
    if (
        global_qa["fair_rows"]
        + global_qa["clearly_worse_rows"]
        + global_qa["excluded_middle_rows"]
        != EXPECTED_ROWS
    ):
        raise RuntimeError("Global fairness regions do not partition the panel")
    if global_qa["draw_nonnegative_rows"] + global_qa["draw_costly_rows"] != EXPECTED_ROWS:
        raise RuntimeError("Global nonnegative/costly indicators do not partition the panel")

    manifests = output_root / "_manifests"
    atomic_write_text(
        manifests / "analysis_panel_paths.txt",
        "".join(f"{path}\n" for path in output_paths),
    )
    atomic_write_text(
        manifests / "input_stage05_paths.txt",
        "".join(f"{receipt['stage05_path']}\n" for receipt in receipts),
    )
    atomic_write_text(
        manifests / "input_stage06_paths.txt",
        "".join(f"{receipt['stage06_path']}\n" for receipt in receipts),
    )
    sf100k_paths = list(
        dict.fromkeys(
            path
            for receipt in receipts
            for path in receipt["sf100k_paths"]
        )
    )
    atomic_write_text(
        manifests / "input_sf100k_paths.txt",
        "".join(f"{path}\n" for path in sf100k_paths),
    )
    atomic_write_json(manifests / "schema.json", receipts[0]["output_schema"])
    atomic_write_json(manifests / "schema_contract.json", contract)
    atomic_write_json(manifests / "authority_sha256.json", authority_sha256)
    month_status = [
        {
            "month": receipt["month"],
            "rows": receipt["output_rows"],
            "output_sha256": receipt["output_sha256"],
            "output_size_bytes": receipt["output_size_bytes"],
            "runtime_seconds": receipt["runtime_seconds"],
            "status": receipt["status"],
            "path": receipt["output_path"],
        }
        for receipt in receipts
    ]
    write_csv_rows(
        manifests / "month_status.csv",
        month_status,
        (
            "month",
            "rows",
            "output_sha256",
            "output_size_bytes",
            "runtime_seconds",
            "status",
            "path",
        ),
    )
    summary = {
        "final_ok": True,
        "status": "STAGE07_24M_CERTIFIED_OK",
        "created_at": utc_now(),
        "script_version": SCRIPT_VERSION,
        "script_sha256": contract["script_sha256"],
        "git_head": git_state["head"],
        "authority_sha256": authority_sha256,
        "output_root": str(output_root),
        "months": 24,
        "month_start": MONTHS[0],
        "month_end": MONTHS[-1],
        "global_qa": global_qa,
        "output_schema": receipts[0]["output_schema"],
        "monthly_outputs": month_status,
        "global_finalization_seconds": time.time() - started,
        "next_step": "Build two-year Stockfish-100k paper results only from this certified panel.",
    }
    atomic_write_json(manifests / "latest_summary.json", summary)
    atomic_write_json(output_root / "_SUCCESS.json", summary)
    logger(
        "GLOBAL: STAGE07_24M_CERTIFIED_OK "
        f"rows={EXPECTED_ROWS:,} unique_game_ids={EXPECTED_ROWS:,} "
        f"kind_draws={EXPECTED_KIND_DRAWS:,}"
    )
    return summary


def fairness_self_test() -> None:
    def classify(value: int) -> str:
        if value >= 300:
            return "disconnected_clearly_better"
        if value > 100:
            return "disconnected_better"
        if value >= -100:
            return "roughly_equal"
        if value > -300:
            return "modestly_worse_excluded"
        return "clearly_worse"

    cases = {
        -10000: "clearly_worse",
        -300: "clearly_worse",
        -299: "modestly_worse_excluded",
        -101: "modestly_worse_excluded",
        -100: "roughly_equal",
        100: "roughly_equal",
        101: "disconnected_better",
        299: "disconnected_better",
        300: "disconnected_clearly_better",
        10000: "disconnected_clearly_better",
    }
    observed = {value: classify(value) for value in cases}
    if observed != cases:
        raise RuntimeError(f"Internal fairness-boundary self-test failed: {observed}")


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Build the fail-closed Stage 07 24-month joined analysis panel."
    )
    parser.add_argument(
        "--execute",
        action="store_true",
        help="Write outputs. Without this flag the script performs a read-only plan.",
    )
    parser.add_argument(
        "--months",
        default="all",
        help="Comma-separated YYYY-MM list, or 'all' (default).",
    )
    parser.add_argument(
        "--output-root",
        type=Path,
        default=DEFAULT_OUTPUT_ROOT,
        help=f"Output root (default: {DEFAULT_OUTPUT_ROOT})",
    )
    parser.add_argument(
        "--temp-root",
        type=Path,
        default=DEFAULT_TEMP_ROOT,
        help=f"DuckDB spill directory (default: {DEFAULT_TEMP_ROOT})",
    )
    parser.add_argument(
        "--threads",
        type=int,
        default=min(8, os.cpu_count() or 1),
        help="DuckDB worker threads (default: min(8, CPU count)).",
    )
    parser.add_argument(
        "--memory-limit",
        default="12GB",
        help="DuckDB memory limit (default: 12GB).",
    )
    return parser.parse_args()


def require_safe_output_root(output_root: Path) -> None:
    resolved = output_root.resolve()
    allowed_parent = (PROJECT / "derived/replication").resolve()
    if resolved == allowed_parent or allowed_parent not in resolved.parents:
        raise RuntimeError(
            "Stage 07 output must be a dedicated child of "
            f"{allowed_parent}; received {resolved}"
        )
    if resolved in {Path("/"), PROJECT.resolve(), REPO.resolve()}:
        raise RuntimeError(f"Refusing broad output target: {resolved}")


def main() -> None:
    args = parse_args()
    if args.threads < 1:
        raise SystemExit("--threads must be at least 1")
    fairness_self_test()

    script_path = Path(__file__).resolve()
    months = parse_months(args.months)
    output_root = args.output_root.expanduser().resolve()
    args.temp_root = args.temp_root.expanduser().resolve()
    require_safe_output_root(output_root)

    if not PROJECT.is_dir():
        raise RuntimeError(f"Project drive/root is unavailable: {PROJECT}")

    git_state = verify_git_state(script_path)
    authority_sha256 = verify_small_authorities()
    verify_summary_contracts()
    parts = discover_sf_parts()
    inventory = verify_monthly_inputs(parts)
    contract = script_contract(script_path)

    if not args.execute:
        print_plan(
            months=months,
            output_root=output_root,
            parts=parts,
            inventory=inventory,
            contract=contract,
            git_state=git_state,
        )
        return

    output_root.mkdir(parents=True, exist_ok=True)
    manifests = output_root / "_manifests"
    current_run_id = run_id()
    current_run_root = manifests / "runs" / current_run_id
    write_execution_manifests(
        run_root=current_run_root,
        output_root=output_root,
        months=months,
        parts=parts,
        inventory=inventory,
        contract=contract,
        authority_sha256=authority_sha256,
        git_state=git_state,
        args=args,
    )
    logger = RunLogger(current_run_root / "run.log")
    logger(
        f"START Stage 07 v{SCRIPT_VERSION}; months={','.join(months)}; "
        f"threads={args.threads}; memory_limit={args.memory_limit}; output={output_root}"
    )

    run_started = time.time()
    receipts_by_month: dict[str, dict[str, Any]] = {}
    for month in months:
        receipts_by_month[month] = build_month(
            month=month,
            parts=parts,
            output_root=output_root,
            temp_root=args.temp_root,
            threads=args.threads,
            memory_limit=args.memory_limit,
            contract=contract,
            authority_sha256=authority_sha256,
            git_state=git_state,
            logger=logger,
        )

    selected_receipts = [receipts_by_month[month] for month in months]
    run_summary: dict[str, Any] = {
        "run_ok": True,
        "status": "STAGE07_SELECTED_MONTHS_OK",
        "created_at": utc_now(),
        "run_id": current_run_id,
        "script_version": SCRIPT_VERSION,
        "script_sha256": contract["script_sha256"],
        "git_head": git_state["head"],
        "months": list(months),
        "rows": sum(receipt["output_rows"] for receipt in selected_receipts),
        "runtime_seconds": time.time() - run_started,
        "monthly_receipts": [
            {
                "month": receipt["month"],
                "path": receipt["output_path"],
                "rows": receipt["output_rows"],
                "sha256": receipt["output_sha256"],
                "status": receipt["status"],
            }
            for receipt in selected_receipts
        ],
    }

    if tuple(months) == MONTHS:
        all_receipts = [receipts_by_month[month] for month in MONTHS]
        global_summary = finalize_global(
            output_root=output_root,
            temp_root=args.temp_root,
            threads=args.threads,
            memory_limit=args.memory_limit,
            receipts=all_receipts,
            contract=contract,
            authority_sha256=authority_sha256,
            git_state=git_state,
            logger=logger,
        )
        run_summary["status"] = "STAGE07_24M_CERTIFIED_OK"
        run_summary["global_summary"] = global_summary
    else:
        logger(
            "PILOT/SELECTED MONTHS COMPLETE: no global _SUCCESS.json was written; "
            "global certification requires all 24 months"
        )

    run_summary["runtime_seconds"] = time.time() - run_started
    atomic_write_json(current_run_root / "run_summary.json", run_summary)
    logger(
        f"DONE status={run_summary['status']} rows={run_summary['rows']:,} "
        f"elapsed={run_summary['runtime_seconds']:,.1f}s"
    )


if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        print("INTERRUPTED: existing certified months were not modified.", file=sys.stderr)
        raise SystemExit(130)
    except Exception as exc:
        print(f"STAGE07_FAIL_CLOSED: {type(exc).__name__}: {exc}", file=sys.stderr)
        raise
